"use client";

import React, { useState } from 'react';
import { Star, MapPin, ShieldCheck, CheckCircle, Clock, ArrowRight } from 'lucide-react';
import { Doctor } from '@/types';
import { useAuth } from '@/lib/auth';
import AuthModal from './AuthModal';

interface DoctorCardProps {
  doctor: Doctor;
  onBook: (id: string, slot: string) => void;
}

const DoctorCard: React.FC<DoctorCardProps> = ({ doctor, onBook }) => {
  const { user } = useAuth();
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingSlot, setPendingSlot] = useState<string | null>(null);

  const handleBookClick = (slot: string) => {
    if (user) {
      onBook(doctor.id, slot);
    } else {
      setPendingSlot(slot);
      setShowAuthModal(true);
    }
  };

  const handleAuthSuccess = () => {
    if (pendingSlot) {
      onBook(doctor.id, pendingSlot);
      setPendingSlot(null);
    }
  };

  return (
    <>
      <div className="card-accent-teal bg-white border border-gray-100 shadow-sm card-lift p-6 mb-4 flex flex-col lg:flex-row gap-6">
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left">
          <div className="relative mb-4">
            <img
              src={doctor.image}
              alt={doctor.name}
              className="w-28 h-28 rounded-2xl object-cover shadow-lg ring-4 ring-white"
            />
            {doctor.isVerified && (
              <div className="absolute -bottom-2 -right-2 bg-doctoralia-teal text-white p-1.5 rounded-full shadow-lg ring-2 ring-white">
                <CheckCircle className="w-4 h-4" />
              </div>
            )}
          </div>
          <h3 className="text-xl font-bold text-gray-900">{doctor.name}</h3>
          <p className="text-coral font-semibold text-sm mb-3">{doctor.specialty}</p>

          <div className="flex items-center gap-1.5 mb-3">
            <div className="flex">
              {[...Array(5)].map((_, i) => (
                <Star key={i} className={`w-4 h-4 ${i >= Math.floor(doctor.rating) ? 'text-gray-200' : 'text-yellow-400 fill-yellow-400'}`} />
              ))}
            </div>
            <span className="text-sm font-bold text-gray-900 ml-1">{doctor.rating}</span>
            <span className="text-xs text-gray-400">({doctor.reviewCount})</span>
          </div>

          <div className="flex items-center gap-2 text-gray-500 text-sm mb-2">
            <MapPin className="w-4 h-4 text-coral" />
            <span>{doctor.address}</span>
          </div>

          <div className="flex items-center gap-2 text-gray-500 text-sm mb-4">
            <ShieldCheck className="w-4 h-4 text-doctoralia-teal" />
            <span className="line-clamp-1">{doctor.insurances.slice(0, 2).join(', ')}{doctor.insurances.length > 2 && '...'}</span>
          </div>

          <button className="text-doctoralia-teal font-semibold text-sm border-2 border-doctoralia-teal px-5 py-2 rounded-xl hover:bg-teal-50 transition flex items-center gap-2 group">
            Ver perfil
            <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
          </button>
        </div>

        <div className="flex-1 flex flex-col">
          <div className="flex items-center gap-2 mb-4 bg-coral-light text-coral p-3 rounded-xl text-sm font-semibold">
            <Clock className="w-4 h-4" />
            Próxima disponibilidad: <span className="text-coral font-bold">Hoy</span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
            {doctor.availability.map((slot, idx) => {
              const date = new Date(slot);
              return (
                <button
                  key={idx}
                  onClick={() => handleBookClick(slot)}
                  className="flex flex-col items-center py-3 px-3 border-2 border-gray-100 rounded-xl hover:border-coral hover:bg-coral-light transition group"
                >
                  <span className="text-xs text-gray-400 capitalize group-hover:text-coral">
                    {date.toLocaleDateString('es-ES', { weekday: 'short', day: 'numeric' })}
                  </span>
                  <span className="font-bold text-gray-800 group-hover:text-coral">
                    {date.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </button>
              );
            })}
            <button className="flex items-center justify-center p-3 text-doctoralia-teal font-bold text-sm bg-teal-50 rounded-xl hover:bg-teal-100 transition">
              Ver más horarios →
            </button>
          </div>

          <div className="mt-6 border-t border-gray-100 pt-4 text-sm text-gray-500">
            <p className="line-clamp-2 italic leading-relaxed">"{doctor.bio}"</p>
          </div>
        </div>
      </div>

      <AuthModal
        isOpen={showAuthModal}
        onClose={() => {
          setShowAuthModal(false);
          setPendingSlot(null);
        }}
        onSuccess={handleAuthSuccess}
      />
    </>
  );
};

export default DoctorCard;
